"""Wave 7 travel-places items (32). Property of Justin Addam Higgins (JAH)."""
import os
from fw import T, mk_item

W7 = os.path.dirname(os.path.abspath(__file__))

TRAVEL_REQS = [
    "Place facts must be verifiable: locations, measurements, and practical details checked.",
    "Travel advice must be responsible: respect local customs, environments, and regulations.",
    "Safety information included where relevant; no reckless guidance.",
    "Cultural sites treated with respect; no religious framing.",
]
TRAVEL_STDS = [
    "Place names and countries given precisely.",
    "Measurements in metric with imperial conversions in demos.",
    "Practical details (best seasons, access) included.",
]
TRAVEL_CITES = [
    "Geographic and cultural facts follow standard published references.",
    "Practical travel details follow official tourism sources.",
]

ITEMS = []

def reg(slug, name, prefix, record_kind, tagline_pub, tagline_sig,
        ai_short, role_pub, role_sig, greet_pub, greet_sig,
        search_ph, chat_ph, gen_blurb, about_archive, topics,
        health=False, gen_extra=""):
    ITEMS.append(mk_item(
        slug=slug, name=name, theme="travel", prefix_pub=prefix,
        record_kind=record_kind, tagline_pub=tagline_pub, tagline_sig=tagline_sig,
        ai_short=ai_short, role_pub=role_pub, role_sig=role_sig,
        greet_pub=greet_pub, greet_sig=greet_sig, search_ph=search_ph,
        chat_ph=chat_ph, gen_blurb=gen_blurb, about_archive=about_archive,
        requirements=TRAVEL_REQS, standards=TRAVEL_STDS, citations=TRAVEL_CITES,
        topics=topics, health=health, gen_sample_extra=gen_extra))

