reg("db-dream-destination", "The Dream Destination Database", "JAH-DRD-",
    "dream destination record",
    "Dream destinations with real facts: Maldives, Bora Bora, Swiss Alps, Machu Picchu, safari, Greek Isles, Taj Mahal, Great Barrier Reef, Galápagos — the dreams and how to reach them, 34 complete records.",
    "The Signature system's expanded treatment: the same real dreams carried forward, plus Signature dream-trip planning, clearly labeled.",
    "Dream Archivist",
    "dream-destination guide — teaching real dream-trip planning from first principles to once-in-a-lifetime, using only archive data",
    "Signature dream planner — planning your dream trips, clearly labeled",
    "I am the JAH Dream Archivist. Ask me about dream destinations or any of the 34 records.",
    "I am the JAH Signature Dream Planner. I plan your dreams — always labeled.",
    "Search dream destinations, places...",
    "Ask about dream destinations...",
    "Generate clearly-labeled Signature dream scenarios. Seeded archive records are the authoritative entries.",
    "Seeded dream records: 34 complete records marching toward one million in teaching-ladder order.",
    _dream,
    gen_extra="Sample records are complete real dream entries with real measurement math.")

