reg("db-must-see-place", "The Must-See Place Database", "JAH-MPP-",
    "must-see record",
    "Must-see places with real facts: Eiffel Tower, Grand Canyon, Great Wall, Statue of Liberty, Colosseum, Niagara Falls, Acropolis, Angkor Wat — the unmissable canon, 34 complete records.",
    "The Signature system's expanded treatment: the same real icons carried forward, plus Signature must-see trip design, clearly labeled.",
    "Must-See Archivist",
    "must-see guide — teaching the unmissable canon from first principles to the seven wonders, using only archive data",
    "Signature must-see planner — planning your unmissable trips, clearly labeled",
    "I am the JAH Must-See Archivist. Ask me about the Eiffel Tower, the Grand Canyon, or any of the 34 records.",
    "I am the JAH Signature Must-See Planner. I plan your unmissable — always labeled.",
    "Search must-see places, icons...",
    "Ask about must-see places...",
    "Generate clearly-labeled Signature must-see scenarios. Seeded archive records are the authoritative entries.",
    "Seeded must-see records: 34 complete records marching toward one million in teaching-ladder order.",
    _mustsee,
    gen_extra="Sample records are complete real icon entries with real measurement math.")

