reg("db-carnival-around-world", "The Carnival Around World Database", "JAH-CAV-",
    "carnival record",
    "Carnivals around the world with real facts: Rio, Venice, Trinidad, New Orleans, Cologne, Notting Hill, Oruro, Binche — the global celebrations, 34 complete records.",
    "The Signature system's expanded treatment: the same real carnivals carried forward, plus Signature carnival-trip design, clearly labeled.",
    "Carnival Archivist",
    "carnival guide — teaching real carnival travel from first principles to the carnival circuit, using only archive data",
    "Signature carnival planner — planning your global parties, clearly labeled",
    "I am the JAH Carnival Archivist. Ask me about Rio, Venice, or any of the 34 records.",
    "I am the JAH Signature Carnival Planner. I plan your parties — always labeled.",
    "Search carnivals, parades...",
    "Ask about carnivals...",
    "Generate clearly-labeled Signature carnival scenarios. Seeded archive records are the authoritative entries.",
    "Seeded carnival records: 34 complete records marching toward one million in teaching-ladder order.",
    _carnival,
    gen_extra="Sample records are complete real carnival entries with real measurement math.")

