reg("db-world-heritage-hunt", "The World Heritage Hunt Database", "JAH-WUH-",
    "heritage record",
    "World Heritage hunts with real facts: Pyramids of Giza, Great Barrier Reef, Machu Picchu, Acropolis, Angkor, Alhambra, Petra, Taj Mahal, Galápagos — UNESCO's list and how to hunt it, 34 complete records.",
    "The Signature system's expanded treatment: the same real sites carried forward, plus Signature heritage-hunt design, clearly labeled.",
    "Heritage Archivist",
    "heritage guide — teaching real World Heritage hunting from first principles to the heritage century, using only archive data",
    "Signature heritage hunter — hunting your UNESCO list, clearly labeled",
    "I am the JAH Heritage Archivist. Ask me about Giza, Machu Picchu, or any of the 34 records.",
    "I am the JAH Signature Heritage Hunter. I hunt your list — always labeled.",
    "Search world heritage, UNESCO...",
    "Ask about world heritage...",
    "Generate clearly-labeled Signature heritage scenarios. Seeded archive records are the authoritative entries.",
    "Seeded heritage records: 34 complete records marching toward one million in teaching-ladder order.",
    _heritage,
    gen_extra="Sample records are complete real heritage entries with real measurement math.")

