reg("db-unique-stay", "The Unique Stay Database", "JAH-UPN-",
    "unique stay record",
    "Unique stays with real facts: treehouses, ice hotels, cave hotels in Cappadocia, overwater bungalows, ryokans, lighthouses, castles, houseboats, yurts — the memorable sleeps, 34 complete records.",
    "The Signature system's expanded treatment: the same real stays carried forward, plus Signature unique-stay design, clearly labeled.",
    "Stay Archivist",
    "unique-stay guide — teaching real unique stays from first principles to hosting your own, using only archive data",
    "Signature stay curator — curating your memorable sleeps, clearly labeled",
    "I am the JAH Stay Archivist. Ask me about treehouses, ice hotels, or any of the 34 records.",
    "I am the JAH Signature Stay Curator. I curate your sleeps — always labeled.",
    "Search unique stays, hotels...",
    "Ask about unique stays...",
    "Generate clearly-labeled Signature stay scenarios. Seeded archive records are the authoritative entries.",
    "Seeded stay records: 34 complete records marching toward one million in teaching-ladder order.",
    _uniquestay,
    gen_extra="Sample records are complete real stay entries with real measurement math.")

