reg("db-glacier-and-iceberg", "The Glacier and Iceberg Database", "JAH-GLM-",
    "glacier record",
    "Glaciers and icebergs with real facts: Perito Moreno, Jostedalsbreen, Athabasca, Ilulissat Icefjord, Vatnajökull, Aletsch, Antarctic bergs — the ice and how to witness it, 34 complete records.",
    "The Signature system's expanded treatment: the same real ice carried forward, plus Signature glacier-trip design, clearly labeled.",
    "Glacier Archivist",
    "glacier guide — teaching real glacier travel from first principles to the ice cap, using only archive data",
    "Signature ice planner — witnessing your glaciers, clearly labeled",
    "I am the JAH Glacier Archivist. Ask me about Perito Moreno, Ilulissat, or any of the 34 records.",
    "I am the JAH Signature Ice Planner. I witness your glaciers — always labeled.",
    "Search glaciers, icebergs...",
    "Ask about glaciers...",
    "Generate clearly-labeled Signature glacier scenarios. Seeded archive records are the authoritative entries.",
    "Seeded glacier records: 34 complete records marching toward one million in teaching-ladder order.",
    _glacier,
    gen_extra="Sample records are complete real glacier entries with real measurement math.")

